import * as T from './assets/three.module.js';
import {createStudioEnvironment} from './studio-environment.js';
import {createModels} from './models.js';
import {HOME_TRANSFORMS} from './scene-layout.js';
import {createFloorReflection} from './floor-reflection.js';
const names=['Writing','Architecture','Research'],cats=[['Essays','Notes','Observations'],['Built Ideas','Academic Projects','Experiential Works'],['Urban Studies','Environmental Systems','Speculative Futures']];
const titles=[['On the Edge of the City','Material and Memory','Cities in Fragments','A Quieter View'],['Light Between Walls','Floating Ground','Threshold','Common Terrain'],['Rivers and Cities','More Than Human']];
const subs=[['Notes on a few thresholds in contemporary space.','A personal inquiry into tangible time.','A set of urban impressions, from inside and afar.','On slowness, attention, and the built environment.'],['Academic Project','Built Idea','Experiential Work','Academic Project'],['Research Project','Speculative Research']];
let floorReflection;
let state='home',selected=0,filter='All',models=[],renderer,scene,camera,transition=null,raf=0,raycaster=new T.Raycaster(),pointer=new T.Vector2(),home=[];
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const $=s=>document.querySelector(s);
function render(){if(renderer&&scene&&camera){floorReflection?.update(camera);renderer.render(scene,camera)}}
function layout(){if(!camera)return;const w=innerWidth,h=innerHeight,a=w/h;renderer.setSize(w,h);camera.aspect=a;const refAspect=1672/941;const refVFov=T.MathUtils.degToRad(27);let fov;if(a<1){fov=55;}else{const matchedVFov=2*Math.atan(Math.tan(refVFov/2)*(refAspect/a));fov=T.MathUtils.radToDeg(matchedVFov);fov=T.MathUtils.clamp(fov,22.6,27);}camera.fov=fov;camera.position.set(0,9,13);camera.lookAt(0,.35,0);camera.updateProjectionMatrix();if(a<1){camera.position.multiplyScalar(1.55);camera.lookAt(0,.2,0)}render();}
function targets(){let mobile=innerWidth/innerHeight<1;return models.map((m,i)=>{if(state==='home')return{x:home[i].x,z:home[i].z,y:0,s:1,r:home[i].r};if(state==='preview'&&i===selected)return{x:mobile?1:2.3,z:mobile?2.7:0,y:0,s:mobile?1.2:1.65,r:home[i].r};return{x:i<=selected?-18:18,z:0,y:0,s:1,r:home[i].r};});}
function animate(){let now=performance.now(),t=Math.min(1,(now-transition.start)/transition.duration),k=t*t*(3-2*t);models.forEach((m,i)=>{let a=transition.from[i],b=transition.to[i];m.position.set(T.MathUtils.lerp(a.x,b.x,k),T.MathUtils.lerp(a.y,b.y,k),T.MathUtils.lerp(a.z,b.z,k));m.scale.setScalar(T.MathUtils.lerp(a.s,b.s,k));m.rotation.y=T.MathUtils.lerp(a.r,b.r,k)});render();if(t<1)raf=requestAnimationFrame(animate);else{transition=null;document.documentElement.dataset.sceneReady='true'}}
function move(){if(!models.length)return;cancelAnimationFrame(raf);document.documentElement.dataset.sceneReady='false';transition={start:performance.now(),duration:reduced?1:state==='index'?550:800,from:models.map(m=>({x:m.position.x,y:m.position.y,z:m.position.z,s:m.scale.x,r:m.rotation.y})),to:targets()};animate();}
function navigate(s,i=selected,push=true){state=s;selected=i;filter='All';document.body.className=state;$('#home-labels').inert=state!=='home';$('#home-bottom').inert=state!=='home';$('footer').inert=state!=='home';$('#category').hidden=state==='home';$('#number').textContent='0'+(i+1);$('#category-title').textContent=names[i];$('#filters').replaceChildren();(state==='index'?['All',...cats[i]]:cats[i]).forEach(c=>{let b=document.createElement('button');b.textContent=c;b.className=c===filter?'active':'';b.onclick=()=>{if(state==='preview'){navigate('index',i);filter=c;}else filter=c;drawIndex();[...$('#filters').children].forEach(x=>x.classList.toggle('active',x.textContent===filter))};$('#filters').append(b)});drawIndex();if(push)history.pushState({state,selected},'',state==='home'?'#home':'#'+names[i].toLowerCase()+'/'+state);move();}
function drawIndex(){let el=$('#index-content');el.replaceChildren();if(state!=='index')return;let wrap=document.createElement('div');wrap.className=selected===0?'writing-list':'gallery '+(selected===2?'research':'');titles[selected].forEach((title,i)=>{let category=cats[selected][selected===1?[1,0,2,1][i]:i%3];if(filter!=='All'&&filter!==category)return;let b=document.createElement('button');b.className=selected===0?'writing-row':'';let img=document.createElement('img');img.src='assets/index-'+([0,4,8][selected]+i)+'.png';img.alt=title+' — reference image';let content=document.createElement('span');let t=document.createElement('span');t.className='item-title';t.textContent=title;let d=document.createElement('span');d.className=selected===0?'item-description':'item-meta';d.textContent=subs[selected][i];content.append(t,d);b.append(img,content);if(selected===0){let date=document.createElement('span');date.className='item-meta date';date.textContent=['Mar 12, 2024','Feb 3, 2024','Jan 18, 2024','Dec 2, 2023'][i];let arr=document.createElement('span');arr.textContent='→';b.append(date,arr)}else{let y=document.createElement('span');y.className='item-meta';y.textContent=i===0?'2024':i===3?'2022':'2023';content.append(y)}b.onclick=()=>showInfo(title,'This title and image reproduce the supplied visual reference. The original project text has not been supplied.');wrap.append(b)});el.append(wrap);}
function showInfo(title,text){$('#info-body').replaceChildren();let h=document.createElement('h2');h.textContent=title;let p=document.createElement('p');p.textContent=text;$('#info-body').append(h,p);$('#info').showModal()}
$('#brand').onclick=()=>navigate('home');$('#archive').onclick=()=>navigate('index',selected);$('#enter').onclick=()=>navigate('index');$('#back').onclick=()=>navigate(state==='index'?'preview':'home');document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>navigate('preview',+b.dataset.category));$('.close').onclick=()=>$('#info').close();$('#info').addEventListener('click',e=>{if(e.target===$('#info'))$('#info').close()});document.querySelectorAll('[data-dialog]').forEach(b=>b.onclick=()=>showInfo(b.dataset.dialog==='about'?'Yuanlong Zhu':'Contact',b.dataset.dialog==='about'?'Thinking through Architecture and the World.':'Contact details will appear here when provided.'));window.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#info').open)navigate(state==='index'?'preview':'home')});window.addEventListener('popstate',()=>readHash(false));function readHash(push=false){let h=location.hash.slice(1).split('/'),i=names.findIndex(x=>x.toLowerCase()===h[0]);navigate(i>=0&&['preview','index'].includes(h[1])?h[1]:'home',Math.max(0,i),push)}
let wheelTime=0;window.addEventListener('wheel',e=>{if(state==='home'&&Math.abs(e.deltaY)>25&&performance.now()-wheelTime>1000){wheelTime=performance.now();navigate('preview',Math.min(2,Math.max(0,Math.floor(e.clientX/innerWidth*3))))}},{passive:true});
async function init(){try{renderer=new T.WebGLRenderer({antialias:true,alpha:false,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;$('#scene').append(renderer.domElement);scene=new T.Scene();scene.background=new T.Color(0xd8dcdf);camera=new T.PerspectiveCamera(27,1,.1,200);let pmrem=new T.PMREMGenerator(renderer);scene.environment=pmrem.fromScene(createStudioEnvironment(),.04).texture;scene.environmentIntensity=1.08;pmrem.dispose();
let loader=new T.TextureLoader();async function tx(name,repeat=1){let t=await loader.loadAsync('assets/'+name);t.wrapS=t.wrapT=T.RepeatWrapping;t.repeat.set(repeat,repeat);return t;}
let [deskMetalColor,deskMetalRough,deskMetalNormal,deskMetalMetalness,linen,paper,stone,print]=await Promise.all([tx('desk-metal-color.png',30),tx('desk-metal-roughness.png',30),tx('desk-metal-normal.png',30),tx('desk-metal-metalness.png',30),tx('linen-bump.png',3),tx('paper-bump.png',2),tx('stone-bump.png',2),tx('research-print.png')]);deskMetalColor.colorSpace=T.SRGBColorSpace;print.colorSpace=T.SRGBColorSpace;print.anisotropy=8;
let ground=new T.Mesh(new T.PlaneGeometry(200,200),new T.MeshPhysicalMaterial({color:0xe6eaec,map:deskMetalColor,envMap:scene.environment,envMapIntensity:1.92,metalness:.98,metalnessMap:deskMetalMetalness,roughness:.74,roughnessMap:deskMetalRough,normalMap:deskMetalNormal,normalScale:new T.Vector2(.18,.18),clearcoat:.08,clearcoatRoughness:.58,anisotropy:.42,anisotropyRotation:0}));ground.rotation.x=-Math.PI/2;ground.position.y=-.016;ground.receiveShadow=true;scene.add(ground);
let hemi=new T.HemisphereLight(0xf9fafb,0x97a0a5,.26);scene.add(hemi);
// Directional light is kept readable and left-biased; specular richness comes mainly from the studio cards.
let key=new T.DirectionalLight(0xfffcf7,1.55);key.position.set(-7.0,10.8,5.5);key.castShadow=true;key.shadow.mapSize.set(2048,2048);Object.assign(key.shadow.camera,{left:-10,right:10,top:8,bottom:-8,near:.1,far:36});key.shadow.bias=-.00012;key.shadow.normalBias=.0075;key.shadow.radius=3.8;scene.add(key);
let keyCompanion=new T.DirectionalLight(0xf7fafc,.64);keyCompanion.position.set(-2.6,8.6,1.9);keyCompanion.castShadow=true;keyCompanion.shadow.mapSize.set(1024,1024);Object.assign(keyCompanion.shadow.camera,{left:-8,right:8,top:6,bottom:-6,near:.1,far:30});keyCompanion.shadow.bias=-.00012;keyCompanion.shadow.normalBias=.0075;keyCompanion.shadow.radius=3.2;scene.add(keyCompanion);
let fill=new T.DirectionalLight(0xeaf0f4,.24);fill.position.set(5.9,7.2,-3.8);scene.add(fill);
floorReflection=createFloorReflection(renderer,scene,ground);
const [linenColor,linenRough,stoneColor,stoneRough,paperColor,copperRough,steelRough]=await Promise.all([tx('linen-color.png',3),tx('linen-rough.png',3),tx('stone-color.png',2),tx('stone-rough.png',2),tx('paper-color.png',2),tx('copper-rough.png'),tx('steel-rough.png')]);for(const t of [linenColor,stoneColor,paperColor]){t.colorSpace=T.SRGBColorSpace;t.anisotropy=Math.min(8,renderer.capabilities.getMaxAnisotropy());}
models=createModels({linen,paper,stone,print,linenColor,linenRough,stoneColor,stoneRough,paperColor,copperRough,steelRough});models.forEach((m,i)=>{const f=HOME_TRANSFORMS[i];m.scale.set(f[2],f[3],f[5]);const root=new T.Group();root.add(m);root.position.set(f[0],0,f[1]);root.rotation.y=f[4];models[i]=root;home.push({x:f[0],z:f[1],r:f[4]});scene.add(root)});layout();readHash();document.fonts.ready.then(render);
renderer.domElement.addEventListener('pointermove',e=>{if(state!=='home')return;pointer.set(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1);raycaster.setFromCamera(pointer,camera);renderer.domElement.style.cursor=raycaster.intersectObjects(models,true).length?'pointer':'default'});renderer.domElement.addEventListener('click',e=>{if(state!=='home')return;pointer.set(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1);raycaster.setFromCamera(pointer,camera);let hit=raycaster.intersectObjects(models,true)[0];if(hit){let root=hit.object;while(root.parent&&!models.includes(root))root=root.parent;let i=models.indexOf(root);if(i>=0)navigate('preview',i)}});window.addEventListener('resize',()=>{layout();move()});renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();$('#failure').hidden=false});
}catch(e){console.error(e);$('#failure').hidden=false;readHash()}}
init();
